function pathHTML(reference,point){
 const branches=reference.points.map(p=>p.result.channels.find(c=>c.id==='creation')?.branches.find(b=>b.index===reference.selection.branchIndex));
 if(branches.some(b=>!Array.isArray(b?.partialSums)))return '';
 const points=branches[point==='A'?0:1].partialSums,range=Math.max(...branches.flatMap(b=>b.partialSums.flatMap(z=>z.map(Math.abs))))||1,w=360,h=290,scale=110/range,xy=z=>[180+z[0]*scale,145-z[1]*scale],ps=points.map(xy),colors=['#1a7563','#286da5','#a66b18','#925b90'];
 return '<div class="pd-plot" data-math-ignore><svg width="360" height="290" viewBox="0 0 360 290" role="img" aria-label="'+esc(T.path)+'"><path d="M12 145H348M180 12V278" stroke="#96aa9d" fill="none"/>'+ps.slice(1).map((p,i)=>'<line x1="'+ps[i][0]+'" y1="'+ps[i][1]+'" x2="'+p[0]+'" y2="'+p[1]+'" stroke="'+colors[i%4]+'" stroke-width="3"/><circle cx="'+p[0]+'" cy="'+p[1]+'" r="4" fill="'+colors[i%4]+'"/>').join('')+'<text x="322" y="137">Re</text><text x="188" y="25">Im</text></svg></div><p>'+esc(T.pathCaption)+'</p>';
}

/** Manual source-bound lesson. No scientific arithmetic or grade is performed by this view. */
export function bindPhonopyDerivationLesson({root,run,download=()=>{},onCopyTeaching,stateStore=memory,stateKey='phonopy-derivation',isCurrent=()=>true}={}){
 let alive=true,job=null,readJob=null,ticket=0,notice='';const owner={};owners.set(root,owner);
 const store=stateStore instanceof Map?stateStore:memory,saved=store.get(stateKey);
 let state=record(saved)?clone(saved):{input:null,sourceMetadata:null,confirmed:false,approximation:false,reference:null,request:null,attempts:{},predictions:{},predictionChecked:{},stage:1,point:'A',disclosures:{givens:true}};
 state.disclosures??={givens:true};
 const current=()=>alive&&owners.get(root)===owner&&root.isConnected!==false&&isCurrent(),$=id=>root.querySelector('#pd-'+id);
 const save=()=>{if(current())store.set(stateKey,clone(state));};
 const attempt=()=>{if(!state.reference)return null;const key=state.reference.fingerprint;return state.attempts[key]??=( {drafts:{},hints:{},revealed:{},feedback:null,submissions:[],referenceAccess:[],note:'',fullReference:{},diagnosis:false,pointChecked:{}} );};
 const access=(kind,taskId,point=state.point)=>{const a=attempt();if(a)a.referenceAccess.push({kind,taskId:taskId??null,point});};
 const retire=()=>{const a=attempt();if(a){a.feedback=null;a.pointChecked={};}state.reference=null;state.request=null;state.stage=1;state.point='A';notice=T.conditionsChanged;};
 const cancel=()=>{if(readJob){readJob.controller.abort();readJob=null;}if(job){const pending=job;job=null;pending.task?.cancel?.();}ticket++;};
 const snapshot=()=>clone(state);
 function sync(){if(!current())return;const busy=!!job||!!readJob;for(const id of ['load','derive','grade','diagnose','reference-export','copy'])if($(id))$(id).disabled=busy||(id==='derive'&&!(state.input&&state.confirmed&&state.approximation));if($('cancel'))$('cancel').disabled=!busy;if($('status'))$('status').textContent=notice;}
 function predictionsHTML(){return '<section class="pd-section"><h4>'+esc(T.prediction)+'</h4><p>'+esc(T.predictionHelp)+'</p>'+predictions.map(p=>'<label for="pd-predict-'+p.id+'">'+esc(p.question)+'</label><select id="pd-predict-'+p.id+'"><option value="">—</option>'+p.options.map((label,i)=>'<option value="'+i+'"'+(state.predictions[p.id]===String(i)?' selected':'')+'>'+esc(label)+'</option>').join('')+'</select>'+button('predict-check-'+p.id,T.predictCheck)+'<p id="pd-predict-feedback-'+p.id+'" role="status">'+(state.predictionChecked[p.id]?esc(p.feedback):'')+'</p>').join('')+'</section>';}
 function sourceHTML(){return '<section class="pd-section"><h4>'+esc(T.source)+'</h4>'+button('load',T.load)+'<p>'+esc(state.input?T.sourceLoaded:T.sourceEmpty)+'</p><p>'+esc(T.fixed)+'</p><label class="pd-check"><input id="pd-confirm" type="checkbox"'+(state.confirmed?' checked':'')+'>'+esc(T.confirm)+'</label><label class="pd-check"><input id="pd-approximation" type="checkbox"'+(state.approximation?' checked':'')+'>'+esc(T.approximation)+'</label>'+(state.sourceMetadata?'<details id="pd-source-details"'+(state.disclosures.source?' open':'')+'><summary>'+esc(T.sourceDetails)+'</summary><p>'+esc(T.sourceReference)+'</p><pre data-math-ignore>'+esc(displayMetadataJSON(state.sourceMetadata))+'</pre></details>':'')+'<div class="pd-actions">'+button('derive',T.manual,'primary')+button('cancel',T.cancel)+'</div></section>';}
 function assisted(t){const a=attempt();return !!(a.hints[t.id]||a.revealed[t.id]||a.referenceAccess.some(x=>x.kind!=='hint-component'&&(x.point==='both'||x.point===t.point||!t.point)));}
 function taskHTML(t){const a=attempt(),draft=a.drafts[t.id]??=(emptyDraft(t)),id=safeId(t.id),h=a.hints[t.id]||0,check=a.feedback?.checks?.find(c=>c.taskId===t.id),labels=['x','y','z'],cellName=(part,r,c)=>t.id+' '+(r+1)+','+(c+1)+' '+(t.shape[1]===3?labels[c]+' ':'')+(part==='re'?T.real:T.imag);
  return '<section class="pd-task" data-pd-task="'+esc(t.id)+'"><h5>'+esc(taskTitle(t))+'</h5><p>'+unit(t.unit)+' · '+esc(assisted(t)?T.assisted:T.unassisted)+'</p><p class="pd-tolerance">'+esc(T.tolerance)+' '+esc(fmt(t.tolerance?.absolute))+' + '+esc(fmt(t.tolerance?.relative))+' × |z|</p>'+(!t.available?'<p>'+esc(T.unavailable)+'</p>':'<div class="pd-answer-grid">'+Array.from({length:t.shape[0]},(_,r)=>Array.from({length:t.shape[1]},(_,c)=>'<fieldset><legend>'+esc(T.component)+' '+(t.shape[1]===3?labels[c]:r+1+','+(c+1))+'</legend><label for="pd-'+id+'-re-'+r+'-'+c+'">'+esc(T.real)+'</label><input inputmode="decimal" autocomplete="off" type="text" id="pd-'+id+'-re-'+r+'-'+c+'" aria-label="'+esc(cellName('re',r,c))+'" data-pd-answer="'+esc(t.id)+'" data-part="re" data-row="'+r+'" data-col="'+c+'" value="'+esc(draft.re[r][c])+'">'+(t.realOnly?'':'<label for="pd-'+id+'-im-'+r+'-'+c+'">'+esc(T.imag)+'</label><input inputmode="decimal" autocomplete="off" type="text" id="pd-'+id+'-im-'+r+'-'+c+'" aria-label="'+esc(cellName('im',r,c))+'" data-pd-answer="'+esc(t.id)+'" data-part="im" data-row="'+r+'" data-col="'+c+'" value="'+esc(draft.im[r][c])+'">')+'</fieldset>').join('')).join('')+'</div><div class="pd-actions">'+button('hint-'+id,T.hint)+button('reveal-'+id,T.reveal)+'</div>'+(h>=1?'<p class="pd-hint">'+esc(T.hintOne)+' '+esc(taskHint(t))+'</p>':'')+(h>=2?'<p>'+esc(T.hintTwo)+'</p>'+formula(formulas[suffix(t)]||''):'')+(h>=3?'<p>'+esc(T.hintThree)+'</p>'+matrixHTML([[t.expected.re[0][0]]],t.realOnly?null:[[t.expected.im[0][0]]]):'')+(a.revealed[t.id]?'<p class="pd-warning">'+esc(T.reference)+'</p>'+matrixHTML(t.expected.re,t.realOnly?null:t.expected.im):''))+(check?'<p class="pd-feedback" role="status">'+esc(({correct:T.correct,incorrect:T.incorrect,missing:T.missing,malformed:T.malformed,unavailable:T.notAvailable})[check.status]||T.invalid)+(finite(check.maxResidual)?' · '+esc(T.residual)+': '+esc(fmt(check.maxResidual)):'')+'</p>':'')+'</section>';
 }
 function givensHTML(ref,point){const r=point.result,b=r.channels.find(c=>c.id==='creation').branches.find(b=>b.index===ref.selection.branchIndex),atom=r.atoms[ref.selection.atomIndex];let html='<details class="pd-givens" id="pd-givens"'+(state.disclosures.givens?' open':'')+'><summary>'+esc(T.givens)+'</summary>';
  if(state.stage===1)html+='<p>'+esc(T.lattice)+'</p>'+matrixHTML(r.structure.lattice)+'<p>'+esc(T.reciprocal)+'</p>'+matrixHTML(r.momentum.reciprocalBasis);
  if(state.stage>=2&&state.stage<=4){const e=b.eigenvector[atom.index];html+='<h5>'+esc(T.selectedData)+': '+esc(atom.index)+' '+esc(atom.symbol)+'</h5><dl><dt>'+esc(T.mass)+'</dt><dd>'+esc(fmt(atom.mass))+'</dd><dt>'+esc(T.position)+'</dt><dd>'+esc(atom.position.map(fmt).join(', '))+'</dd><dt>'+esc(T.length)+'</dt><dd>'+esc(fmt(atom.coherentLengthFm))+'</dd></dl><p>'+esc(T.rawEigen)+'</p><div class="pd-scroll pd-given-vector" tabindex="0"><table><thead><tr><th>'+esc(T.component)+'</th><th>'+esc(T.real)+'</th><th>'+esc(T.imag)+'</th></tr></thead><tbody>'+e.map((z,i)=>'<tr><th scope="row">'+['x','y','z'][i]+'</th><td>'+esc(fmt(z[0]))+'</td><td>'+esc(fmt(z[1]))+'</td></tr>').join('')+'</tbody></table></div><p>'+esc(T.relative)+'</p><details id="pd-all-atoms"'+(state.disclosures.allAtoms?' open':'')+'><summary>'+esc(T.allAtoms)+'</summary><div class="pd-scroll" tabindex="0"><table><thead><tr><th>'+esc(T.atom)+'</th><th>'+esc(T.mass)+'</th><th>'+esc(T.position)+'</th><th>'+esc(T.length)+'</th><th>e</th></tr></thead><tbody>'+r.atoms.map(a=>'<tr><th scope="row">'+esc(a.index)+' '+esc(a.symbol)+(a.index===atom.index?' ←':'')+'</th><td>'+esc(fmt(a.mass))+'</td><td>'+esc(a.position.map(fmt).join(', '))+'</td><td>'+esc(fmt(a.coherentLengthFm))+'</td><td>'+matrixHTML([b.eigenvector[a.index].map(z=>z[0])],[b.eigenvector[a.index].map(z=>z[1])])+'</td></tr>').join('')+'</tbody></table></div></details>';}
  if(state.stage===3)html+='<p class="pd-hint">'+esc(T.massDefinition)+'</p>'+formula(String.raw`\frac{\mathbf Q\cdot\mathbf e_\kappa^*}{\sqrt{m_\kappa}}=\mathbf Q\cdot\left(\frac{\mathbf e_\kappa^*}{\sqrt{m_\kappa}}\right)`);
  if(state.stage===5)html+='<p>'+esc(T.thermalGiven)+'</p><dl><dt>'+esc(T.energy)+'</dt><dd>'+esc(fmt(b.energyMeV))+'</dd><dt>'+esc(T.quantum)+'</dt><dd>'+esc(fmt(b.quantumFactor))+'</dd><dt>'+esc(T.occupation)+'</dt><dd>'+esc(fmt(b.occupation))+'</dd></dl>';
  return html+'</details>';
 }
 function derivationHTML(){if(!state.reference)return '';const a=attempt(),ref=state.reference,tasks=ref.tasks.filter(t=>(!t.point||t.point===state.point)&&t.stage===state.stage),point=ref.points.find(p=>p.id===state.point);
  let html='<section class="pd-section"><h4>'+esc(T.learnFirst)+'</h4><p>'+esc(T.identity)+'</p><div class="pd-point-tabs">'+button('point-A',T.pointA,state.point==='A'?'primary':'secondary')+button('point-B',T.pointB,state.point==='B'?'primary':'secondary')+'</div><p class="pd-current">'+esc(state.point)+' · q = '+esc(JSON.stringify(point.result.momentum.q))+' · G = '+esc(JSON.stringify(point.input.G))+' · T = '+esc(fmt(point.input.temperature))+' K · DW omit<br>'+esc(T.selected)+': '+esc(ref.selection.atomIndex)+'</p><div class="pd-actions">'+button('back',T.back)+'<strong id="pd-step">'+esc(T.stage)+' '+state.stage+' / 5</strong>'+button('next',T.next)+'</div>'+givensHTML(ref,point)+'<p>'+esc(T.taskHelp)+'</p><form id="pd-answer-form">'+tasks.map(taskHTML).join('')+'</form><p>'+esc(T.checkNote)+'</p><p>'+esc(T.phaseScope)+'</p><div class="pd-actions">'+button('grade',T.check,'primary')+'</div><p class="pd-grade-note" role="status">'+esc(a.feedback?T.feedbackHelp:T.noFeedback)+'</p>'+(a.feedback?.diagnosis?.usedTaskIds?.length?'<div class="pd-diagnostic-summary" role="status">'+diagnosticSummary(a.feedback.diagnosis)+'</div>':'');
  html+='<label for="pd-note">'+esc(T.note)+'</label><textarea id="pd-note" rows="4">'+esc(a.note)+'</textarea><p>'+esc(T.noteHelp)+'</p><div class="pd-actions">'+button('show-reference',T.fullReference)+'</div>';
  if(a.fullReference[state.point])html+='<section class="pd-reference"><h5>'+esc(T.physical)+'</h5><p class="pd-warning">'+esc(T.fullWarning)+'</p>'+ref.tasks.filter(t=>!t.point||t.point===state.point).map(t=>'<h6>'+esc(taskTitle(t))+'</h6>'+(t.available?matrixHTML(t.expected.re,t.realOnly?null:t.expected.im):'<p>'+esc(T.unavailable)+'</p>')).join('')+pathHTML(ref,state.point)+'</section>';
  html+='<section class="pd-diagnosis"><h5>'+esc(T.diagnosis)+'</h5><p>'+esc(T.diagnosisHelp)+'</p>'+button('diagnose',T.diagnose)+(a.diagnosis?diagnosisHTML(ref):'')+'</section><div class="pd-actions">'+button('learning-export',T.exportLearning)+button('reference-export',T.exportReference)+(onCopyTeaching?button('copy',T.copy):'')+'</div><p>'+esc(T.exportBoundary)+'</p><p>'+esc(T.original)+'</p></section>';return html;
 }
 function diagnosticSummary(d){const labels=candidateLabels();return '<p>'+esc(d.hasBothPoints?T.both:T.one)+' · '+esc(T.referenceCompatible)+': '+esc(d.referenceCompatible?T.yes:T.no)+'</p>'+(!d.hasBothPoints?'<p>'+esc(T.oneFeedback)+'</p>':'')+'<p>'+esc(T.compatible)+': '+(d.compatibleCandidates?.length?d.compatibleCandidates.map(id=>esc(labels[id]||id)).join(', '):esc(T.none))+'</p>';}
 function diagnosisHTML(ref){const labels=candidateLabels(),d=attempt().feedback?.diagnosis;
  const contrastRows=(ref.contrasts||[]).map(c=>'<tr><th scope="row">'+esc(labels[c.id]||c.id)+'</th>'+['A','B'].map(id=>'<td>'+esc(fmt(c.points?.find(p=>p.id===id)?.strength))+'</td>').join('')+(c.distinguishableByPoint||[]).map(v=>'<td>'+esc(v?T.yes:T.no)+'</td>').join('')+'</tr>').join('');
  return '<p class="pd-warning">'+esc(T.fullWarning)+'</p>'+(d?diagnosticSummary(d):'')+'<div class="pd-scroll" tabindex="0"><table><caption>'+esc(T.diagnosis)+'</caption><thead><tr><th>'+esc(T.candidates)+'</th><th>'+esc(T.strengthA)+'</th><th>'+esc(T.strengthB)+'</th><th>'+esc(T.distinguishA)+'</th><th>'+esc(T.distinguishB)+'</th></tr></thead><tbody>'+contrastRows+'</tbody></table></div><p>'+esc(T.diagnosisBoundary)+'</p>';
 }
 function bind(){
  const rendered=root.querySelector('.pd-lesson'),active=()=>current()&&root.querySelector('.pd-lesson')===rendered;
  for(const [id,key]of [['source-details','source'],['givens','givens'],['all-atoms','allAtoms']])if($(id)){const n=$(id);n.ontoggle=()=>{if(active()){state.disclosures[key]=typeof n.open==='boolean'?n.open:n.getAttribute('open')!==null;save();}};}
  for(const p of predictions){const n=$('predict-'+p.id);n.onchange=()=>{if(!active())return;state.predictions[p.id]=n.value;delete state.predictionChecked[p.id];$('predict-feedback-'+p.id).textContent='';save();};$('predict-check-'+p.id).onclick=()=>{if(!current()||!n.value)return;state.predictionChecked[p.id]=true;$('predict-feedback-'+p.id).textContent=p.feedback;save();};}
  $('load').onclick=()=>{if(active())return load();};for(const [id,key]of [['confirm','confirmed'],['approximation','approximation']]){const n=$(id);n.onchange=()=>{if(!active())return;cancel();state[key]=n.checked;if(state.reference)retire();save();draw();};}$('derive').onclick=()=>{if(active())return derive();};$('cancel').onclick=()=>{if(!active())return;cancel();notice=T.cancelled;save();sync();};
  if(!state.reference)return;
  const a=attempt();for(const id of ['A','B'])$('point-'+id).onclick=()=>{if(!active())return;state.point=id;save();draw();};
  $('back').disabled=state.stage===1;$('next').disabled=state.stage===5;for(const [id,delta]of [['back',-1],['next',1]])$(id).onclick=()=>{if(!active())return;state.stage=Math.max(1,Math.min(5,state.stage+delta));save();draw();};
  const form=$('answer-form');form.onsubmit=e=>e.preventDefault();form.oninput=e=>{if(!active())return;const n=e.target,t=state.reference.tasks.find(t=>t.id===n.dataset?.pdAnswer);if(!t)return;const r=Number(n.dataset.row),c=Number(n.dataset.col),part=n.dataset.part;if(!['re','im'].includes(part)||!Number.isInteger(r)||!Number.isInteger(c))return;cancel();a.drafts[t.id][part][r][c]=n.value;a.feedback=null;if(t.point)a.pointChecked[t.point]=false;else a.pointChecked={};notice='';save();sync();if(root.querySelector('.pd-grade-note'))root.querySelector('.pd-grade-note').textContent=T.noFeedback;for(const feedback of root.querySelectorAll('.pd-feedback'))feedback.textContent='';};
  for(const t of state.reference.tasks.filter(t=>(!t.point||t.point===state.point)&&t.stage===state.stage&&t.available)){const id=safeId(t.id);$('hint-'+id).onclick=()=>{if(!active())return;a.hints[t.id]=Math.min(3,(a.hints[t.id]||0)+1);if(a.hints[t.id]===3)access('hint-component',t.id);save();draw();};$('reveal-'+id).onclick=()=>{if(!active())return;a.revealed[t.id]=true;access('task-answer',t.id);save();draw();};}
  $('grade').onclick=()=>{if(active())return grade();};$('note').oninput=()=>{if(active()){a.note=$('note').value;save();}};$('show-reference').onclick=()=>{if(!active())return;a.fullReference[state.point]=true;access('point-reference');save();draw();};
  $('diagnose').onclick=()=>{if(!active())return;if(!['A','B'].every(p=>a.pointChecked[p]&&a.drafts[p+'.coherentStrength']?.re?.[0]?.[0]?.trim())){notice=T.diagnosisNeed;sync();return;}a.diagnosis=true;access('two-point-diagnosis',null,'both');save();draw();};
  $('learning-export').onclick=()=>{if(!active())return;download(JSON.stringify({kind:'phonopy-scattering-learning',schema:'symmetry-lab-phonopy-derivation-learning-1',fingerprint:state.reference.fingerprint,sourceBundle:state.reference.sourceBundle,conditions:state.reference.conditions,selection:state.reference.selection,request:clone(state.request),predictions:clone(state.predictions),predictionFeedbackAccess:clone(state.predictionChecked),attempt:clone(a)},null,2),'phonopy-derivation-learning.json','application/json');};
  $('reference-export').onclick=()=>{if(!active())return;access('full-reference-export',null,'both');save();download(JSON.stringify({action:'phonopy_derivation',input:clone(state.request),result:clone(state.reference)},null,2),'phonopy-derivation-reference.json','application/json');};
  if($('copy'))$('copy').onclick=()=>{if(!active())return;access('expert-reference-copy');save();const p=state.reference.points.find(p=>p.id===state.point),ok=onCopyTeaching({action:'phonopy_scattering',input:clone(p.input),referenceId:'zno-two-point-derivation',fingerprint:state.reference.fingerprint,point:state.point,sourceKind:'teaching-reference'});notice=ok===false?T.copyFailed:T.copyDone;sync();};
 }
 function draw(){if(!current())return;root.innerHTML='<section class="pd-lesson"><h3>'+esc(T.title)+'</h3><p>'+esc(T.intro)+'</p>'+predictionsHTML()+sourceHTML()+'<p id="pd-status" role="status"></p>'+derivationHTML()+'</section>';bind();sync();save();}
 async function load(){if(!current()||job||readJob)return;cancel();const request={id:++ticket,controller:new AbortController()};readJob=request;notice=T.wait;sync();try{const data=await loadPhonopyScatteringZnO({signal:request.controller.signal});if(!current()||readJob!==request)return;const input=inputFromZnO(data);state.input=input;state.sourceMetadata={primary:data.scatteringMetadata.primary,structure:data.scatteringMetadata.structure,probe:data.scatteringMetadata.probe,phononGeneration:data.scatteringMetadata.phononGeneration};state.confirmed=false;state.approximation=false;if(state.reference)retire();readJob=null;notice=T.sourceLoaded;draw();}catch(error){if(current()&&readJob===request){readJob=null;notice=String(error.message||T.error);sync();}}}
 function request(){return {input:clone(state.input),comparisonG:[1,0,0],branchIndex:10,atomIndex:2};}
 async function derive(){if(!current()||job||readJob)return;if(!state.input||!state.confirmed||!state.approximation){notice=T.needSource;sync();return;}const input=request();await execute(input,false);}
 function answers(){const a=attempt(),out={};for(const t of state.reference.tasks){const d=a.drafts[t.id];if(!d||!t.available)continue;const components=t.realOnly?[d.re]:[d.re,d.im],strings=components.flat(2);if(strings.every(s=>!s.trim()))continue;if(strings.some(s=>!numericText(s)))throw Error(T.format);out[t.id]={re:d.re.map(row=>row.map(Number)),im:t.realOnly?d.re.map(row=>row.map(()=>0)):d.im.map(row=>row.map(Number))};}return out;}
 async function grade(){if(!current()||job||readJob||!state.reference)return;let submitted;try{submitted=answers();}catch(error){notice=error.message;sync();return;}const a=attempt(),input={...clone(state.request),mode:'grade',answers:submitted,forFingerprint:state.reference.fingerprint};await execute(input,true,{rawAnswers:clone(a.drafts),hints:clone(a.hints),revealed:clone(a.revealed),referenceAccess:clone(a.referenceAccess),point:state.point});}
 async function execute(input,grading,context){const request={id:++ticket,input:clone(input),task:null,fingerprint:state.reference?.fingerprint};job=request;notice=T.wait;sync();try{request.task=run('phonopy_derivation',clone(input));const result=await request.task;if(!current()||job!==request)return;if(phonopyDerivationModel(result).status!=='available'||grading&&(result.fingerprint!==request.fingerprint||!record(result.grading)||!Array.isArray(result.grading.checks)))throw Error(T.invalid);job=null;if(grading){const a=attempt();a.feedback=clone(result.grading);a.pointChecked[context.point]=true;a.submissions.push({point:context.point,answers:clone(input.answers),forFingerprint:input.forFingerprint,rawAnswers:context.rawAnswers,hints:context.hints,revealed:context.revealed,referenceAccess:context.referenceAccess,grading:clone(result.grading)});}else{state.reference=result;state.request=clone(input);state.point='A';state.stage=1;attempt();}notice=grading?T.feedbackHelp:T.ready;draw();}catch(error){if(current()&&job===request){job=null;notice=String(error.message||T.error);sync();save();}}}
 draw();
 const cleanup=()=>{if(!alive)return;save();cancel();alive=false;if(owners.get(root)!==owner)return;owners.delete(root);for(const n of root.querySelectorAll('button'))n.onclick=null;for(const n of root.querySelectorAll('select'))n.onchange=null;for(const n of root.querySelectorAll('input'))n.onchange=null;for(const n of root.querySelectorAll('details'))n.ontoggle=null;const form=$('answer-form');if(form){form.oninput=null;form.onsubmit=null;}if($('note'))$('note').oninput=null;};cleanup.snapshot=snapshot;return cleanup;
}
